        $value->unsetEnabledUserEmail();
        $this->assertEquals('other', $value->getEnabledUserEmailOrCurrent(TenantConfigEnabledUserEmailVO::from($enabledUserEmailOtherValue))->value());
        $this->assertNotEquals('one', $value->getEnabledUserEmailOrCurrent(TenantConfigEnabledUserEmailVO::from($enabledUserEmailOtherValue))->value());
        $allowRecoverPassOneValue = true;
        $allowRecoverPassOtherValue = false;
        $copy = $value->allowRecoverPass($allowRecoverPassOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isAllowRecoverPass());
