        $this->assertNotEquals(false, $value->getAllowRecoverPassOrCurrent(TenantConfigAllowRecoverPassVO::from($allowRecoverPassOtherValue))->value());
        $value->unsetAllowRecoverPass();
        $this->assertEquals(false, $value->getAllowRecoverPassOrCurrent(TenantConfigAllowRecoverPassVO::from($allowRecoverPassOtherValue))->value());
        $this->assertNotEquals(true, $value->getAllowRecoverPassOrCurrent(TenantConfigAllowRecoverPassVO::from($allowRecoverPassOtherValue))->value());
        $recoverPassEmailOneValue = 'one';
        $recoverPassEmailOtherValue = 'other';
