        $this->assertEquals('one', $value->getRecoverPassEmail());
        $this->assertNotEquals('other', $value->getRecoverPassEmail());
        $this->assertEquals('one', $value->getRecoverPassEmailOrCurrent(TenantConfigRecoverPassEmailVO::from($recoverPassEmailOtherValue))->value());
        $this->assertNotEquals('other', $value->getRecoverPassEmailOrCurrent(TenantConfigRecoverPassEmailVO::from($recoverPassEmailOtherValue))->value());
        $value->unsetRecoverPassEmail();
        $this->assertEquals('other', $value->getRecoverPassEmailOrCurrent(TenantConfigRecoverPassEmailVO::from($recoverPassEmailOtherValue))->value());
        $this->assertNotEquals('one', $value->getRecoverPassEmailOrCurrent(TenantConfigRecoverPassEmailVO::from($recoverPassEmailOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
