        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(TenantConfigVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(TenantConfigVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
